import h5py
import numpy as np

# Open one NWB file to explore structure
f = h5py.File('data/sub-m11/sub-m11_ses-03_behavior+ophys.nwb', 'r')

def print_structure(name, obj):
    if isinstance(obj, h5py.Dataset):
        print(f"  DATASET: {name}, shape={obj.shape}, dtype={obj.dtype}")
    elif isinstance(obj, h5py.Group):
        print(f"  GROUP: {name}")

print("Top-level keys:")
for key in f.keys():
    print(f"  {key}")

print("\n--- Processing modules ---")
if 'processing' in f:
    for key in f['processing'].keys():
        print(f"  {key}")
        for subkey in f['processing'][key].keys():
            print(f"    {subkey}")
            if isinstance(f['processing'][key][subkey], h5py.Group):
                for subsubkey in f['processing'][key][subkey].keys():
                    item = f['processing'][key][subkey][subsubkey]
                    if isinstance(item, h5py.Dataset):
                        print(f"      {subsubkey}: shape={item.shape}, dtype={item.dtype}")
                    else:
                        print(f"      {subsubkey} (group)")

f.close()
